CREATE TABLE "statuses" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "category" INTEGER NOT NULL, "sort_order" INTEGER NOT NULL);
CREATE TABLE "industries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE);
CREATE TABLE "companies" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "status_id" INTEGER NOT NULL REFERENCES statuses (id), "mypage_id" TEXT NULL, "mypage_url" TEXT NULL, "use_custom_reminders" INTEGER NOT NULL DEFAULT 0 CHECK ("use_custom_reminders" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL);
CREATE TABLE "company_industries" ("company_id" INTEGER NOT NULL REFERENCES companies (id) ON DELETE CASCADE, "industry_id" INTEGER NOT NULL REFERENCES industries (id) ON DELETE CASCADE, PRIMARY KEY ("company_id", "industry_id"));
CREATE TABLE "events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "company_id" INTEGER NOT NULL REFERENCES companies (id) ON DELETE CASCADE, "type" INTEGER NOT NULL, "title" TEXT NULL, "starts_at" INTEGER NOT NULL);
CREATE TABLE "company_reminders" ("company_id" INTEGER NOT NULL REFERENCES companies (id) ON DELETE CASCADE, "minutes_before" INTEGER NOT NULL, PRIMARY KEY ("company_id", "minutes_before"));
CREATE TABLE "logs" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "company_id" INTEGER NOT NULL REFERENCES companies (id) ON DELETE CASCADE, "kind" INTEGER NOT NULL, "body" TEXT NOT NULL DEFAULT '', "from_status" TEXT NULL, "to_status" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
